$(document).ready(function(){$("#profil").submit(function(a){a.preventDefault();var t=$(this);let e={nama:$("#nama").val(),nik:$("#nik").val(),dep:$("#departemen").val(),jab:$("#jab").val(),atasan:$("#atasan").val(),bos:$("#bos").val(),tgl_lahir:$("#tgl_lahir").val(),nip:$("#nip").val()};if($("#atasan").val()==""){Swal.fire({icon:"error",title:"Wajib ada atasan"});return}if($("#departemen").val()=="")return Swal.fire({icon:"error",text:"Bidang departemen harus diisi."});$.ajax({url:"/api/updateProfile",method:"POST",data:e,success:function(r){Swal.fire({icon:"success",title:"Berhasil",text:"Data berhasil diubah"})},error:function(r){Swal.fire({icon:"error",title:"Gagal",text:"Data gagal diubah"})}})})});
